import{_ as a,o as i,c as t,a2 as o}from"./chunks/framework.iXqqCa-C.js";const r="/images/misskey-reaction-picker.webp",u=JSON.parse('{"title":"回应与表情符号","description":"","frontmatter":{},"headers":[],"relativePath":"guide/misskey/reactions.md","filePath":"guide/misskey/reactions.md","lastUpdated":1793076233000}'),s={name:"guide/misskey/reactions.md"};function l(n,e,c,d,m,h){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="回应与表情符号" tabindex="-1">回应与表情符号 <a class="header-anchor" href="#回应与表情符号" aria-label="Permalink to &quot;回应与表情符号&quot;">​</a></h1><h2 id="回应" tabindex="-1">回应 <a class="header-anchor" href="#回应" aria-label="Permalink to &quot;回应&quot;">​</a></h2><p>回应（Reaction）是 Misskey 特色互动方式：用任意 Emoji 表达态度，而不只是点赞。</p><ul><li>点击帖子下方的 <strong>+</strong> 打开回应选择器，选一个 Emoji 即可回应。</li><li>与点赞不同，回应可以表达喜怒哀乐（😂 😭 👍 ❤️ 等任意表情）。</li><li>点击帖子已有的回应可以查看回应者列表；再点一次自己发出的回应即可取消。</li><li>服务器管理员可以上传自定义表情，扩充可用的回应。</li></ul><h2 id="回应相关的设置" tabindex="-1">回应相关的设置 <a class="header-anchor" href="#回应相关的设置" aria-label="Permalink to &quot;回应相关的设置&quot;">​</a></h2><ul><li><strong>将回应设置为公开</strong>（设置 → 隐私）：开启后，他人可在你主页的「回应」标签看到你发出的回应。</li><li><strong>接受表情回应</strong>（设置 → 个人资料）：限制别人在你的帖子上能用的回应，可选全部、仅限非敏感内容、仅点赞。</li></ul><h2 id="表情符号调色板" tabindex="-1">表情符号调色板 <a class="header-anchor" href="#表情符号调色板" aria-label="Permalink to &quot;表情符号调色板&quot;">​</a></h2><p>发帖或回应时弹出的表情选择器：</p><ul><li>支持 Unicode Emoji 与服务器自定义表情（<code>:自定义表情:</code> 格式）。</li><li>在「设置 → 表情符号调色板」创建多个调色板，分别指定用于回应和用于发帖的调色板，并调整选择器的显示方式（弹出 / 抽屉）、大小、列数。</li><li>发帖输入框上方的 MFM 功能菜单中也能快速插入表情。</li></ul><p><img src="'+r+'" alt="回应选择器"></p><p>相关页面：<a href="/guide/posts">帖子与时间线</a>中的「互动」一节、<a href="/guide/misskey/mfm">MFM 语法</a>。</p>',11)])])}const _=a(s,[["render",l]]);export{u as __pageData,_ as default};
